import type { Transition } from "motion/react";
export const DEFAULT_ANIMATION_EASING = "cubic-bezier(0.85, 0, 0.15, 1)";
export const DEFAULT_ANIMATION_DURATION_MS = 1100;
export const DEFAULT_CHART_ENTER_TRANSITION: Transition = {
    type: "tween",
    duration: 1.1,
    ease: [0.85, 0, 0.15, 1],
};
/** SVG width reveals require a tween even when series enter uses a spring. */
export function clipRevealTransition(enterTransition?: Transition): Transition {
    if (enterTransition?.type === "tween") {
        return { ...enterTransition, ease: enterTransition.ease ?? DEFAULT_CHART_ENTER_TRANSITION.ease };
    }
    return {
        type: "tween",
        duration: typeof enterTransition?.duration === "number" ? enterTransition.duration : DEFAULT_ANIMATION_DURATION_MS / 1000,
        ease: DEFAULT_CHART_ENTER_TRANSITION.ease,
    };
}

"use client";
import { animate, useMotionValue, type Transition } from "motion/react";
import { useEffect, useRef } from "react";
import { DEFAULT_CHART_ENTER_TRANSITION } from "./animation";
export function useMountProgress(enterTransition: Transition | undefined, delaySeconds: number, replayKey: number | string, reducedMotion: boolean) {
    const progress = useMotionValue(reducedMotion ? 1 : 0);
    const transitionRef = useRef(enterTransition);
    transitionRef.current = enterTransition;
    useEffect(() => {
        if (reducedMotion) {
            progress.set(1);
            return;
        }
        progress.set(0);
        const controls = animate(progress, 1, {
            ...(transitionRef.current ?? DEFAULT_CHART_ENTER_TRANSITION),
            delay: delaySeconds,
        });
        return () => controls.stop();
    }, [delaySeconds, replayKey, progress, reducedMotion]);
    return progress;
}

"use client";
import type { MotionValue } from "motion/react";
import { useEffect, useState } from "react";
export function useEnterComplete(progress: MotionValue<number>): boolean {
    const [complete, setComplete] = useState(() => progress.get() >= 1);
    useEffect(() => {
        setComplete(progress.get() >= 1);
        // Observe resets as well as completion when a segment's index changes.
        return progress.on("change", (value) => {
            if (value <= 0)
                setComplete(false);
            else if (value >= 1)
                setComplete(true);
        });
    }, [progress]);
    return complete;
}

"use client";
import { useSyncExternalStore } from "react";
const query = "(prefers-reduced-motion: reduce)";
function subscribe(callback: () => void) {
    const media = window.matchMedia(query);
    media.addEventListener("change", callback);
    return () => media.removeEventListener("change", callback);
}
function getSnapshot() { return window.matchMedia(query).matches; }
function getServerSnapshot() { return false; }
/** Hydrate the same entrance markup as SSR, then apply the visitor preference. */
export function useChartReducedMotion() {
    return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}
